from manim import *
RUN = []

class LearningProcessScene(Scene):
    def construct(self):
        title = Text({{title}}, font_size=42).scale_to_fit_width(11).to_edge(UP)
        steps = {{steps}}
        if not 2 <= len(steps) <= 5 or not all(isinstance(x, str) and x.strip() for x in steps):
            raise ValueError("steps must contain 2 to 5 non-empty strings")
        self.add(title)
        previous = None
        for i, step in enumerate(steps):
            number = Text(str(i + 1), font_size=42, color=YELLOW)
            body = Text(step, font_size=38).scale_to_fit_width(10)
            card = VGroup(number, body).arrange(DOWN, buff=0.5).move_to(ORIGIN)
            slot = RUN[i] if i < len(RUN) else 3.5
            duration = min(1.4, slot * 0.5)
            if previous is None:
                self.play(FadeIn(card), run_time=duration)
            else:
                self.play(FadeOut(previous), FadeIn(card), run_time=duration)
            self.wait(max(0, slot - duration))
            previous = card
